-- REVIEW ONLY. Owner approval, verified recovery, maintenance and preflight are required.
-- DDL is not transactionally atomic. Stop on any error; never reset/retry a partial migration.
-- This plan does not create verified balances, grant privileges, update old guards or activate expense masters or Money Accounts.
-- Execute as the existing upms_guard85@localhost definer after separately verified authority.
DELIMITER $$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_employees_delete` BEFORE DELETE ON `employees` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_employees_insert` BEFORE INSERT ON `employees` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (NEW.version<>1 OR CHAR_LENGTH(TRIM(NEW.name))<1 OR NEW.created_at<>NEW.updated_at OR NEW.name_key NOT REGEXP '^[a-f0-9]{64}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_employees_update` BEFORE UPDATE ON `employees` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (NEW.id<>OLD.id OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR CHAR_LENGTH(TRIM(NEW.name))<1 OR NEW.name_key NOT REGEXP '^[a-f0-9]{64}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_categories_delete` BEFORE DELETE ON `expense_categories` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_categories_insert` BEFORE INSERT ON `expense_categories` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (NEW.version<>1 OR CHAR_LENGTH(TRIM(NEW.name))<1 OR NEW.created_at<>NEW.updated_at OR NEW.name_key NOT REGEXP '^[a-f0-9]{64}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_categories_update` BEFORE UPDATE ON `expense_categories` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (NEW.id<>OLD.id OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR CHAR_LENGTH(TRIM(NEW.name))<1 OR NEW.name_key NOT REGEXP '^[a-f0-9]{64}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_master_audit_delete` BEFORE DELETE ON `expense_master_audit` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_master_audit_insert` BEFORE INSERT ON `expense_master_audit` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND ((NEW.action='CREATE' AND NEW.version<>1) OR (NEW.action='UPDATE' AND NEW.version<2) OR NOT ((NEW.entity='CATEGORY' AND EXISTS(SELECT 1 FROM expense_categories m WHERE m.id=NEW.entity_id AND m.version=NEW.version AND m.actor_id=NEW.actor_id AND m.updated_at=NEW.created_at AND BINARY m.name=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.snapshot,'$.name')) AND JSON_UNQUOTE(JSON_EXTRACT(NEW.snapshot,'$.id'))=CAST(m.id AS CHAR))) OR (NEW.entity='EMPLOYEE' AND EXISTS(SELECT 1 FROM employees m WHERE m.id=NEW.entity_id AND m.version=NEW.version AND m.actor_id=NEW.actor_id AND m.updated_at=NEW.created_at AND BINARY m.name=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.snapshot,'$.name')) AND JSON_UNQUOTE(JSON_EXTRACT(NEW.snapshot,'$.id'))=CAST(m.id AS CHAR))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_master_audit_update` BEFORE UPDATE ON `expense_master_audit` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_schema_receipts_delete` BEFORE DELETE ON `expense_schema_receipts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_schema_receipts_insert` BEFORE INSERT ON `expense_schema_receipts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32b2_expense_schema_receipts_update` BEFORE UPDATE ON `expense_schema_receipts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_EXPENSE_PROTECTED'; END IF; END$$
DELIMITER ;
